SELECT "t8"."line_id", "t8"."item_on_hand", COALESCE("t12"."quantity_on_hand", 0) AS "variant_on_hand"
FROM (SELECT "t3"."line_id", "t3"."request_number", "t3"."item", "t3"."quantity", "t3"."unit_price", "t3"."line_value", "t3"."reason", "t3"."requested_resolution", "t3"."requested_variant", "t3"."customer", "t3"."customer_email", "t3"."order_number", "t3"."requested_date", "t3"."customer_id", "t3"."addr", "t3"."cdemo", "t3"."hdemo", "t3"."birth_year", "t3"."center", "t3"."email", "t7"."as_of_date", "t7"."quantity_on_hand", "t7"."_ttrp_g_n31_0", "t7"."_ttrp_g_n31_1", COALESCE("t7"."quantity_on_hand", 0) AS "item_on_hand"
        FROM (SELECT "t2"."line_id", "t2"."request_number", "t2"."item", "t2"."quantity", "t2"."unit_price", "t2"."line_value", "t2"."reason", "t2"."requested_resolution", "t2"."requested_variant", "t2"."customer", "t2"."customer_email", "t2"."order_number", "t2"."requested_date", "customer0"."customer_id", "customer0"."addr", "customer0"."cdemo", "customer0"."hdemo", "customer0"."birth_year", "customer0"."center", "customer0"."email"
                FROM (SELECT "line_id", "request_number", "item", "quantity", "unit_price", "quantity" * "unit_price" AS "line_value", "reason", "requested_resolution", "requested_variant", "customer0" AS "customer", "email" AS "customer_email", "order_number", "requested_date"
                        FROM (SELECT "t"."line_id", "t"."request_number", "t"."line_no", "t"."item", "t"."quantity", "t"."unit_price", "t"."reason", "t"."requested_resolution", "t"."requested_variant", "t"."state", "t"."way", "t"."customer", "t"."customer0", "t"."order_number", "t"."channel", "t"."requested_date", "t"."state0", "customer"."customer_id", "customer"."addr", "customer"."cdemo", "customer"."hdemo", "customer"."birth_year", "customer"."center", "customer"."email"
                                FROM (SELECT "return_request_line"."line_id", "return_request_line"."request_number", "return_request_line"."line_no", "return_request_line"."item", "return_request_line"."quantity", "return_request_line"."unit_price", "return_request_line"."reason", "return_request_line"."requested_resolution", "return_request_line"."requested_variant", "return_request_line"."state", "return_request_line"."way", "return_request_line"."customer", "return_request"."customer" AS "customer0", "return_request"."order_number", "return_request"."channel", "return_request"."requested_date", "return_request"."state" AS "state0"
                                        FROM "return_request_line"
                                            INNER JOIN "return_request" ON "return_request_line"."request_number" = "return_request"."request_number") AS "t"
                                    LEFT JOIN "customer" ON "t"."customer" = "customer"."sk") AS "t0"
                        WHERE "t0"."state" = 'received') AS "t2"
                    INNER JOIN "customer" AS "customer0" ON "t2"."customer" = "customer0"."sk") AS "t3"
            LEFT JOIN (SELECT "t4"."as_of_date", "t4"."item", "t4"."warehouse", "t4"."quantity_on_hand", "t4"."_ttrp_g_n31_0", "t4"."_ttrp_g_n31_1"
                FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n31_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n31_1"
                        FROM "inventory") AS "t4"
                    INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n31_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n31_1", MAX("as_of_date") AS "_ttrp_latest_n31"
                        FROM "inventory"
                        GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t6" ON "t4"."_ttrp_g_n31_0" = "t6"."_ttrp_g_n31_0" AND "t4"."_ttrp_g_n31_1" = "t6"."_ttrp_g_n31_1" AND "t4"."as_of_date" = "t6"."_ttrp_latest_n31") AS "t7" ON "t3"."item" = "t7"."item" AND "t3"."center" = "t7"."warehouse") AS "t8"
    LEFT JOIN (SELECT "t9"."as_of_date", "t9"."item", "t9"."warehouse", "t9"."quantity_on_hand", "t9"."_ttrp_g_n31_0", "t9"."_ttrp_g_n31_1"
        FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n31_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n31_1"
                FROM "inventory") AS "t9"
            INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n31_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n31_1", MAX("as_of_date") AS "_ttrp_latest_n31"
                FROM "inventory"
                GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t11" ON "t9"."_ttrp_g_n31_0" = "t11"."_ttrp_g_n31_0" AND "t9"."_ttrp_g_n31_1" = "t11"."_ttrp_g_n31_1" AND "t9"."as_of_date" = "t11"."_ttrp_latest_n31") AS "t12" ON "t8"."requested_variant" = "t12"."item" AND "t8"."center" = "t12"."warehouse"
